package com.goldwithdrawamount;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.time.Instant;

public class GoldWithdrawAmountOverlay extends Overlay
{
    private static final int DISPLAY_DURATION_MS = 10000;

    private final Client client;
    private Instant showUntil;

    @Inject
    private GoldWithdrawAmountOverlay(Client client)
    {
        this.client = client;
        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    public void trigger()
    {
        showUntil = Instant.now().plusMillis(DISPLAY_DURATION_MS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (showUntil == null || Instant.now().isAfter(showUntil))
        {
            return null;
        }

        String text = "High gold withdrawal!";
        graphics.setFont(new Font("Arial", Font.BOLD, 18));


        FontMetrics metrics = graphics.getFontMetrics();
        int x = 10;
        int y = 50;

        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x - 1, y - 1);
        graphics.drawString(text, x + 1, y - 1);
        graphics.drawString(text, x - 1, y + 1);
        graphics.drawString(text, x + 1, y + 1);

        graphics.setColor(Color.RED);
        graphics.drawString(text, x, y);

        return new Dimension(metrics.stringWidth(text), metrics.getHeight());
    }
}

package com.goldwithdrawamount;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
        name = "Gold Withdraw Warning",
        description = "Warns you when withdrawing more than your set gold threshold.",
        tags = {"gold", "bank", "warning", "ironman"}
)
public class GoldWithdrawAmountPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private GoldWithdrawAmountOverlay overlay;

    @Inject
    private GoldWithdrawAmountConfig config;

    private int lastBankGold = 0;
    private int lastInventoryGold = 0;

    @Provides
    GoldWithdrawAmountConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GoldWithdrawAmountConfig.class);
    }

    @Override
    protected void startUp()
    {
        log.info("Gold Withdraw Amount plugin started");
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        log.info("Gold Withdraw Amount plugin stopped");
        overlayManager.remove(overlay);
        lastBankGold = 0;
        lastInventoryGold = 0;
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (!config.enabled())
        {
            return;
        }

        ItemContainer container = event.getItemContainer();

        if (container == null)
        {
            return;
        }

        if (event.getContainerId() == InventoryID.BANK.getId())
        {
            lastBankGold = getGoldAmount(container);
        }

        if (event.getContainerId() == InventoryID.INVENTORY.getId())
        {
            int currentInventoryGold = getGoldAmount(container);

            if (currentInventoryGold > lastInventoryGold && lastBankGold > 0)
            {
                int withdrawn = currentInventoryGold - lastInventoryGold;
                if (withdrawn >= config.threshold())
                {
                    sendWarning(withdrawn);
                }
            }

            lastInventoryGold = currentInventoryGold;
        }
    }

    private int getGoldAmount(ItemContainer container)
    {
        int total = 0;

        if (container == null || container.getItems() == null)
        {
            return 0;
        }

        for (net.runelite.api.Item item : container.getItems())
        {
            if (item.getId() == ItemID.COINS_995)
            {
                total += item.getQuantity();
            }
        }

        return total;
    }

    private void sendWarning(int amount)
    {
        String msg = "<col=ff0000>Warning: You withdrew " + amount +
                " coins! (Threshold: " + config.threshold() + ")</col>";


        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(msg)
                        .build()
        );


        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.GAMEMESSAGE)
                        .runeLiteFormattedMessage(msg)
                        .build()
        );


        overlay.trigger();
    }
}

package com.goldwithdrawamount;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("goldwithdrawamount")
public interface GoldWithdrawAmountConfig extends Config
{
    @ConfigItem(
            keyName = "enabled",
            name = "Enable warning",
            description = "Toggle the gold withdrawal warning on or off"
    )
    default boolean enabled()
    {
        return true;
    }

    @ConfigItem(
            keyName = "threshold",
            name = "Gold threshold",
            description = "Warn when withdrawing this amount of gold or more"
    )
    default int threshold()
    {
        return 10000;
    }
}

package com.goldwithdrawamount;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GoldWithdrawAmountPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GoldWithdrawAmountPlugin.class);
		RuneLite.main(args);
	}
}
